package com.iare.club.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="payment_detection_events",uniqueConstraints=@UniqueConstraint(name="uk_payment_detection_delivery",columnNames={"provider","delivery_id"}))public class PaymentDetectionEvent{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="payment_reference",length=100)private String paymentReference;@Column(nullable=false,length=40)private String provider;@Column(name="delivery_id",nullable=false,length=150)private String deliveryId;@Column(name="event_type",nullable=false,length=60)private String eventType;@Column(precision=18,scale=2)private BigDecimal amount;@Column(length=150)private String utr;@Column(name="settlement_state",length=40)private String settlementState;@Column(nullable=false)private boolean matched;@Column(length=500)private String detail;@Column(name="received_at",nullable=false)private Instant receivedAt;protected PaymentDetectionEvent(){}public PaymentDetectionEvent(String ref,String provider,String delivery,String event,BigDecimal amount,String utr,String settlement,boolean matched,String detail,Instant at){paymentReference=ref;this.provider=provider;deliveryId=delivery;eventType=event;this.amount=amount;this.utr=utr;settlementState=settlement;this.matched=matched;this.detail=detail;receivedAt=at;}}
